import{_ as a,o as s,c as n,a2 as o}from"./chunks/framework.Di-jvWLj.js";const y=JSON.parse('{"title":"OpenClaw","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/openclaw.md","filePath":"deployment/openclaw.md","lastUpdated":1793100580000}'),t={name:"deployment/openclaw.md"};function l(p,e,c,r,d,i){return s(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="openclaw" tabindex="-1">OpenClaw <a class="header-anchor" href="#openclaw" aria-label="Permalink to &quot;OpenClaw&quot;">​</a></h1><p>OpenClaw is a personal assistant gateway that connects chat channels to agents. chamvi&#39;s integration contract is <strong>&quot;MCP in, hooks out&quot;</strong>.</p><h2 id="mcp-in" tabindex="-1">MCP in <a class="header-anchor" href="#mcp-in" aria-label="Permalink to &quot;MCP in&quot;">​</a></h2><p>Each chamvi app serves an MCP endpoint at <code>/mcp</code> (Streamable HTTP, from <a href="/guide/http#mcp"><code>@chamvi/http</code></a>). OpenClaw lists it among its MCP servers and gets:</p><ul><li>one <code>run_&lt;agent&gt;</code> tool per agent with an <code>http.on()</code> subscription, which starts a run (channel <code>mcp</code>) and returns the run id (or, with <code>waitSeconds</code>, waits up to a minute and returns the output or the pending approval),</li><li><code>get_run</code> and <code>list_runs</code> for status,</li><li><code>approve_run</code>, which needs <code>agent:&lt;name&gt;:approve</code>: OpenClaw&#39;s principal should not hold it (see below), so for OpenClaw it always fails.</li></ul><p>The endpoint uses the same bearer-token authentication as the REST API; give OpenClaw a principal with <code>agent:&lt;name&gt;:run</code>, which also lets it read the runs it starts. Never give it <code>agent:&lt;name&gt;:approve</code>: the owner answers approvals in the chamvi UI, signed in as a principal of their own. This is how the owner says &quot;what&#39;s relevant in my mail today?&quot; in a chat and gets a run started.</p><h2 id="hooks-out" tabindex="-1">Hooks out <a class="header-anchor" href="#hooks-out" aria-label="Permalink to &quot;Hooks out&quot;">​</a></h2><p>Messages and approval requests flow back through the OpenClaw <a href="/guide/channels">channel</a>, <a href="/reference/channel-openclaw"><code>@chamvi/channel-openclaw</code></a>: <code>POST &lt;openclaw&gt;&lt;hooks.path&gt;/agent</code> with OpenClaw&#39;s hooks token as bearer token, the message key as <code>Idempotency-Key</code> header and the delivery target (channel and recipient). The channel is out only:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> openclaw = openclawChannel({</span></span>
<span class="line"><span style="color:#958A8B;">    // the OpenClaw gateway, reachable from the app</span></span>
<span class="line"><span style="color:#E6DFDE;">    baseUrl: </span><span style="color:#E7C58C;">&#39;http://openclaw:18789&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">    // OpenClaw&#39;s hooks.token, not the gateway token</span></span>
<span class="line"><span style="color:#E6DFDE;">    hooksToken: process.env.OPENCLAW_HOOKS_TOKEN </span><span style="color:#FF7B84;">??</span><span style="color:#E7C58C;"> &#39;&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">    // placeholders: the channel and recipient of your OpenClaw setup</span></span>
<span class="line"><span style="color:#E6DFDE;">    deliver: { channel: </span><span style="color:#E7C58C;">&#39;&lt;channel&gt;&#39;</span><span style="color:#E6DFDE;">, to: </span><span style="color:#E7C58C;">&#39;&lt;recipient&gt;&#39;</span><span style="color:#E6DFDE;"> },</span></span>
<span class="line"><span style="color:#958A8B;">    // optional: a link to the approval in the UI; a message never carries the token</span></span>
<span class="line"><span style="color:#E6DFDE;">    approvalUrl: ({ runId, approvalId }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E7C58C;"> \`https://chamvi.example/ui/approvals?run=</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">encodeURIComponent</span><span style="color:#E6DFDE;">(</span><span style="color:#E7C58C;">runId</span><span style="color:#E6DFDE;">)</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">&amp;approval=</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">encodeURIComponent</span><span style="color:#E6DFDE;">(</span><span style="color:#E7C58C;">approvalId</span><span style="color:#E6DFDE;">)</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">\`</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> engine = </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> Engine({</span></span>
<span class="line"><span style="color:#E6DFDE;">    store: </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> MemoryStore(),</span></span>
<span class="line"><span style="color:#E6DFDE;">    agents,</span></span>
<span class="line"><span style="color:#958A8B;">    // tools reach it with ctx.channels.findOneOrFail(&#39;openclaw&#39;)</span></span>
<span class="line"><span style="color:#E6DFDE;">    channels: [openclaw],</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p>A tool sends through it with <code>ctx.channels.findOne(&#39;openclaw&#39;)</code>: <code>emit()</code> for a message, <code>approve()</code> to pause the call until the owner answers. The address is the recipient; without one the call sends to <code>deliver.to</code>, the channel&#39;s <code>defaultAddress</code>:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> const</span><span style="color:#E6DFDE;"> deploy = defineTool({</span></span>
<span class="line"><span style="color:#E6DFDE;">    description: </span><span style="color:#E7C58C;">&#39;Deploy the current release.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    inputSchema: z.object({ env: z.enum([</span><span style="color:#E7C58C;">&#39;staging&#39;</span><span style="color:#E6DFDE;">, </span><span style="color:#E7C58C;">&#39;prod&#39;</span><span style="color:#E6DFDE;">]) }),</span></span>
<span class="line"><span style="color:#E6DFDE;">    execute: </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> ({ env }, { context }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#FF7B84;">        const</span><span style="color:#E6DFDE;"> openclaw = context.channels.findOneOrFail(</span><span style="color:#E7C58C;">&#39;openclaw&#39;</span><span style="color:#E6DFDE;">);</span></span>
<span class="line"><span style="color:#958A8B;">        // without an address both go to deliver.to (the channel&#39;s defaultAddress)</span></span>
<span class="line"><span style="color:#FF7B84;">        const</span><span style="color:#E6DFDE;"> { approved } = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> openclaw.approve({ title: </span><span style="color:#E7C58C;">\`Deploy to </span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">env</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">?\`</span><span style="color:#E6DFDE;"> });</span></span>
<span class="line"><span style="color:#FF7B84;">        if</span><span style="color:#E6DFDE;"> (</span><span style="color:#FF7B84;">!</span><span style="color:#E6DFDE;">approved) </span><span style="color:#FF7B84;">return</span><span style="color:#E7C58C;"> &#39;the owner said no&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#FF7B84;">        await</span><span style="color:#E6DFDE;"> openclaw.emit({ body: </span><span style="color:#E7C58C;">\`Deployed to </span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">env</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">.\`</span><span style="color:#E6DFDE;"> });</span></span>
<span class="line"><span style="color:#FF7B84;">        return</span><span style="color:#E7C58C;"> \`deployed to </span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">env</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">\`</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p>In the OpenClaw configuration:</p><table tabindex="0"><thead><tr><th>Key</th><th>Value</th></tr></thead><tbody><tr><td><code>hooks.enabled</code></td><td><code>true</code> (hooks are off by default)</td></tr><tr><td><code>hooks.token</code></td><td>A dedicated token, passed as <code>hooksToken</code>; not the gateway token</td></tr><tr><td><code>hooks.path</code></td><td><code>/hooks</code> (the default <code>hooksPath</code>), or the same value on both sides</td></tr><tr><td><code>hooks.allowedAgentIds</code></td><td>Lists the <code>agentId</code> you pass, if any</td></tr><tr><td><code>mcp.servers</code></td><td>The app&#39;s <code>/mcp</code> endpoint with a token of a principal holding <code>agent:&lt;name&gt;:run</code>, never <code>agent:&lt;name&gt;:approve</code></td></tr></tbody></table><p><code>deliver.channel</code> and <code>deliver.to</code> must name a concrete destination of your OpenClaw setup (OpenClaw refuses <code>channel: &#39;last&#39;</code> and a partial destination for hooks); the examples use placeholders.</p><p>For approvals the message includes how to answer: the <code>approvalUrl</code> link when configured, e.g. <code>https://&lt;app&gt;/ui/approvals?run=&lt;runId&gt;&amp;approval=&lt;approvalId&gt;</code>, which opens the run&#39;s approval in the UI, where the signed-in owner answers it through <code>POST /runs/:id/approve</code> (the owner&#39;s principal needs <code>agent:&lt;agent&gt;:approve</code> to answer and <code>run:read</code> or <code>agent:&lt;agent&gt;:run</code> for the UI to show the run&#39;s approval); else a line saying to answer in the chamvi UI or through <code>POST /runs/:id/approve</code>.</p><div class="warning custom-block"><p class="custom-block-title">The OpenClaw agent cannot approve</p><p>The approval&#39;s title and body are what the tool wrote and may repeat untrusted text (an issue body, a mail). OpenClaw wraps hook content as external, but that does not take tools away. The message carries no token, so a relay agent whose principal holds only <code>agent:&lt;name&gt;:run</code> cannot approve, whatever an injected instruction says: only the owner, signed in to the UI, approves.</p></div><h3 id="caveats" tabindex="-1">Caveats <a class="header-anchor" href="#caveats" aria-label="Permalink to &quot;Caveats&quot;">​</a></h3><ul><li>OpenClaw runs an agent turn on the message (it does not post raw text) and treats it as external content; the message asks that agent to keep every link and id verbatim.</li><li>OpenClaw&#39;s idempotency replay is in memory and lasts 5 minutes after completion; a restart clears it. chamvi&#39;s records (the emit effect, the approval&#39;s <code>waiting.notifiedAt</code> and its per-approval lock) are the primary dedupe, the key covers a response lost within those minutes.</li><li>A misconfigured hook (400, 401, 404) fails on every send: an <code>emit()</code> is a tool error, an approval message reaches <code>onError</code> on every poll.</li><li>Keys over 256 characters (which OpenClaw ignores) or with characters outside visible ASCII are sent as <code>sha256:&lt;hex&gt;</code>.</li></ul><h2 id="in-the-cluster" tabindex="-1">In the cluster <a class="header-anchor" href="#in-the-cluster" aria-label="Permalink to &quot;In the cluster&quot;">​</a></h2><p>OpenClaw runs elsewhere in the cluster. It reaches each app at <code>http://&lt;service&gt;/mcp</code>, and the app reaches OpenClaw&#39;s hooks endpoint. Neither needs to be public.</p>`,20)])])}const E=a(t,[["render",l]]);export{y as __pageData,E as default};
